    UpdateIfEqual(y - chunk.WorldPos.Y, Chunk.ChunkSize - 1, new WorldPos(x, y + 1, z));
    UpdateIfEqual(z - chunk.WorldPos.Z, 0, new WorldPos(x, y, z - 1));
    UpdateIfEqual(z - chunk.WorldPos.Z, Chunk.ChunkSize - 1, new WorldPos(x, y, z + 1));
}

