    alterStatement = $@"ALTER TABLE [{tableName}] DROP COLUMN ValidFrom, COLUMN ValidTo";
    migrationBuilder.Sql(alterStatement);
    alterStatement = $@"DROP TABLE [{temporalScheme}].[{temporalTableName}]";
    migrationBuilder.Sql(alterStatement);
}

