	uint price = 0;
	uint m = 1;
	for (var i = NumBitLevels; i > 0; i--)
	{
		var bit = symbol & 1;
		symbol >>= 1;
		price += Models[m].GetPrice(bit);
		m = (m << 1) | bit;
	}
	return price;
}

