public static async Task<int> ReadAllAsync(this Stream stream, byte[] buffer, int offset, int count)
{
    int total = 0;
    var remaining = count;
    while (remaining > 0)
    {
        int readCount = await stream.ReadAsync(buffer, offset, remaining);
        total += readCount;
        if (readCount == 0)
        {
            break;
        }

        offset += readCount;
        remaining -= readCount;
    }

    return total;
}

