private bool MatchTitleLine(Token token, TokenType tokenType)
{
    if (token.IsEOF)
        return false;

    var keywords = currentDialect.GetTitleKeywords(tokenType);
    foreach (var keyword in keywords)
    {
        if (token.Line.StartsWith(keyword, ':'))
        {
            token.MatchedType = tokenType;
            token.MatchedKeyword = keyword;
            token.Text = token.Line.GetRestTrimmed(keyword.Length + 1);
            languageChangeAllowed = false;
            return true;
        }
    }
    return false;
}

private List<int> CleanDuplicateRouteElements(List<int> routeElements)
{
    List<int> routes = new List<int>();
    int lastElement = int.MinValue;
    foreach (var element in routeElements)
    {
        if (lastElement != element)
        {
            routes.Add(element);
            lastElement = element;
        }
    }

    return routes;
}

