        var notifier = IoC.Resolve<INotify<GearRole>>();
        var users = args.Invited?.Select(x => x.ToGuid()).ToList() ?? new List<Guid>();
        if (users.Any())
        {
            await notifier.SendNotificationAsync(users, NotificationType.Info, subject, message);
        }
    };

