    if (line.InstructionName.Equals(".endrepeat"))
    {
        if (_repetition < 1)
            throw new ExpressionException(line.Instruction.Position, $"Missing matching \".repeat\" directive.");

        if (--_repetition > 0)
            LineIterator.Rewind(Index);
        return true;
    }
    return line.InstructionName.Equals(".repeat");
}

