	if (Body != null)
	for (int i = 0 ; i != Body.Length ; i++) {
		if (i == 0) {}
		else if (i % 32 == 0)
			w.WriteLine ();
		else if (i % 4 == 0)
			w.Write (' ');

		w.Write (Body[i].ToString ("x2", System.Globalization.CultureInfo.InvariantCulture));
