public bool Equals(Dictionary<TKey, TValue> x, Dictionary<TKey, TValue> y)
{
    if (x.Count != y.Count)
        return false;
    if (x.Keys.Except(y.Keys).Any())
        return false;
    if (y.Keys.Except(x.Keys).Any())
        return false;
    foreach (var pair in x)
        if (!valueComparer.Equals(pair.Value, y[pair.Key]))
            return false;
    return true;
}

