    }

    IGraphData childGraphData;

    if (phantomChildrenGraphsData.TryGetValue(element.guid, out childGraphData))
    {
        // Debug.Log($"Restoring phantom child graph data for {element}.");
        phantomChildrenGraphsData.Remove(element.guid);
