public void NextBatch(ulong[] buffer, int index, int count)
{
    ulong x = this.lastX;
    ulong y = this.lastY;
    ulong z = this.lastZ;
    ulong w = this.lastW;

    for (int i = 0; i < count; i++)
    {
        ulong t = x ^ (x << 11);
        x = y;
        y = z;
        z = w;
        w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));

        buffer[index + i] = w;
    }

    this.lastX = x;
    this.lastY = y;
    this.lastZ = z;
    this.lastW = w;
}

