public bool TryGetImageType(string pathName, out ImageFormat type)
{
    var ext = Path.GetExtension(pathName)?.ToLower();
    switch (ext)
    {
        case ".jpg":
        case ".jpeg":
            type = ImageFormat.Jpeg;
            break;
        case ".png":
            type = ImageFormat.Png;
            break;
        case ".bmp":
            type = ImageFormat.Bmp;
            break;
        default:
            type = null;
            return false;
    }
    return true;
}

