public static IEnumerator TimedJoin(this IResumable resumable, float waitTime)
{
    if (waitTime > 0 && !resumable.Finished)
        resumable.Resume(Coroutine.Delta);

    while (waitTime > 0 && !resumable.Finished)
    {
        yield return null;
        waitTime -= Coroutine.Delta;
        resumable.Resume(Coroutine.Delta);
    }
}

