private static int DecodeBCD(byte[] data)
{
    int result = 0;

    for (int i = data.Length - 1; i >= 0; i--)
    {
        result *= 100;
        result += (10 * (data[i] >> 4));
        result += data[i] & 0x0F;
    }

    return result;
}

