    if (HasSharedVertexBuffer(gltfMesh))
    {
        meshContext.ImportMeshSharingVertexBuffer(data, gltfMesh, inverter);
    }
    else
    {
        meshContext.ImportMeshIndependentVertexBuffer(data, gltfMesh, inverter);
