    while (length > buffer.Length)
    {
        _stream.Read(buffer, 0, buffer.Length);
        stream.Write(buffer, 0, buffer.Length);

        length = length - buffer.Length;
    }
    _stream.Read(buffer, 0, length);
    stream.Write(buffer, 0, length);
}

