private static byte[] GetPadded(BigInteger n, int length)
{
	byte[] bs = BigIntegers.AsUnsignedByteArray(n);
	if (bs.Length < length)
	{
		byte[] tmp = new byte[length];
		Array.Copy(bs, 0, tmp, length - bs.Length, bs.Length);
		bs = tmp;
	}
	return bs;
}

