static bool ReadFromHex (Stream ms, string hex)
{
	if (hex.StartsWith ("#"))
		return true;

	int i = 0;
	while (i < hex.Length) {
		if (char.IsWhiteSpace (hex [i])) {
			i++;
			continue;
		}

		if (hex [i] == '.') {
			ms.Flush ();
			return false;
		}

		byte res = (byte) (FromHexChar (hex [i++]) << 4);
		res += FromHexChar (hex [i++]);
		ms.WriteByte (res);
	}

	ms.Flush ();
	return true;
}

