				{
					tout.WriteLine("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
					tout.WriteLine(doc.OuterXml);
				}
			}
		}

		Console.WriteLine("done.\n");
	}
	catch (SyntaxException)
