public override long Seek(long offset, SeekOrigin origin)
{
    switch (origin)
    {
        case SeekOrigin.Begin: Position = offset; break;
        case SeekOrigin.Current: Position += offset; break;
        case SeekOrigin.End: Position = Length - offset; break;
    }
    return Position;
}

